import csv
import json
import math
from dataclasses import dataclass
from json.encoder import INFINITY, _make_iterencode, encode_basestring, encode_basestring_ascii
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


ROOT = Path(__file__).resolve().parent


class TwoDecimalFloatEncoder(json.JSONEncoder):
    """JSON encoder that prints floats with exactly 2 decimal places.

    This keeps currency fields as JSON numbers (not strings) while ensuring the
    serialized artifact shows 2 decimals as required by the task.
    """

    def iterencode(self, o, _one_shot=False):
        # Largely based on Python's json.encoder.JSONEncoder.iterencode
        if self.check_circular:
            markers = {}
        else:
            markers = None

        _encoder = encode_basestring_ascii if self.ensure_ascii else encode_basestring

        def floatstr(
            value,
            allow_nan=self.allow_nan,
            _inf=INFINITY,
            _neginf=-INFINITY,
        ):
            if math.isnan(value):
                text = "NaN"
            elif value == _inf:
                text = "Infinity"
            elif value == _neginf:
                text = "-Infinity"
            else:
                # Force two decimals.
                return format(value, ".2f")
            if not allow_nan:
                raise ValueError(
                    "Out of range float values are not JSON compliant: " + repr(value)
                )
            return text

        _iterencode = _make_iterencode(
            markers,
            self.default,
            _encoder,
            self.indent,
            floatstr,
            self.key_separator,
            self.item_separator,
            self.sort_keys,
            self.skipkeys,
            _one_shot,
        )
        return _iterencode(o, 0)


def load_json(path: Path) -> Any:
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def load_csv(path: Path) -> List[Dict[str, str]]:
    with path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        return list(reader)


def is_blank(value: Optional[str]) -> bool:
    return value is None or str(value).strip() == ""


def to_float(value: Any, default: float = 0.0) -> float:
    if value is None:
        return default
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).strip()
    if s == "":
        return default
    try:
        return float(s)
    except ValueError:
        return default


def to_int(value: Any, default: int = 0) -> int:
    if value is None:
        return default
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    s = str(value).strip()
    if s == "":
        return default
    try:
        return int(float(s))
    except ValueError:
        return default


def r2(value: float) -> float:
    # A tiny epsilon reduces "-0.00" artifacts when values cancel.
    v = round(float(value) + 0.0, 2)
    if v == -0.0:
        return 0.0
    return v


def flatten_manifest_panels(panel_manifest: Dict[str, Any]) -> List[Dict[str, Any]]:
    panels: List[Dict[str, Any]] = []
    for cluster in panel_manifest.get("service_clusters", []):
        for panel in cluster.get("panels", []):
            panels.append(panel)
    return panels


def build_holdout_excludes(holdouts_json: Dict[str, Any]) -> set:
    excluded = set()
    for h in holdouts_json.get("holdouts", []):
        if str(h.get("holdout_state", "")).strip() == "exclude":
            code = str(h.get("panel_code", "")).strip()
            if code:
                excluded.add(code)
    return excluded


def resolve_base_payment_for_panel(
    panel: Dict[str, Any], contract_rows: List[Dict[str, str]]
) -> float:
    panel_name = str(panel.get("panel_name", "")).strip()
    alias_labels = panel.get("alias_labels")
    aliases: List[str] = []
    if isinstance(alias_labels, list):
        aliases = [str(a).strip() for a in alias_labels if not is_blank(a)]

    candidates = {panel_name, *aliases}

    matches: List[Dict[str, str]] = []
    for row in contract_rows:
        if str(row.get("status_flag", "")).strip() != "current":
            continue
        ref = str(row.get("panel_ref", "")).strip()
        if ref in candidates:
            matches.append(row)

    if not matches:
        return 0.0

    # latest effective_week wins; format is ISO-ish (e.g., 2026-W22), so
    # lexicographic compare is sufficient.
    matches.sort(key=lambda r: str(r.get("effective_week", "")).strip())
    winning = matches[-1]
    return to_float(winning.get("base_payment_per_run_per_lab_usd"), default=0.0)


def build_network_adjustments_map(rows: List[Dict[str, str]]) -> Dict[str, float]:
    out: Dict[str, float] = {}
    for r in rows:
        tier = str(r.get("network_tier", "")).strip()
        if tier:
            out[tier] = to_float(r.get("network_adjustment_per_run_per_lab_usd"), 0.0)
    return out


def build_shipper_cost_map(rows: List[Dict[str, str]]) -> Dict[str, float]:
    out: Dict[str, float] = {}
    for r in rows:
        cls = str(r.get("shipper_class", "")).strip()
        if cls:
            out[cls] = to_float(r.get("shipper_cost_usd"), 0.0)
    return out


def build_active_labs_override_map(
    rows: List[Dict[str, str]]
) -> Dict[str, Tuple[float, int]]:
    """Return panel_code -> (rev, active_labs) for highest rev valid override."""

    best: Dict[str, Tuple[float, int]] = {}
    for r in rows:
        if str(r.get("approval", "")).strip() != "approved":
            continue
        panel_code = str(r.get("panel_code", "")).strip()
        rev_raw = r.get("rev")
        labs_raw = r.get("active_labs")
        if is_blank(panel_code) or is_blank(rev_raw) or is_blank(labs_raw):
            continue

        rev = to_float(rev_raw, default=float("nan"))
        if math.isnan(rev):
            continue
        labs = to_int(labs_raw, default=-1)
        if labs < 0:
            continue

        prev = best.get(panel_code)
        if prev is None or rev > prev[0]:
            best[panel_code] = (rev, labs)

    return best


def main() -> None:
    panel_manifest = load_json(ROOT / "panel_manifest.json")
    shipper_cost_rows = load_csv(ROOT / "shipper_cost.csv")
    contract_rows = load_csv(ROOT / "contract_terms.csv")
    network_rows = load_csv(ROOT / "network_adjustments.csv")
    lab_override_rows = load_csv(ROOT / "lab_capacity_overrides.csv")
    holdouts_json = load_json(ROOT / "holdouts.json")
    report_template = load_json(ROOT / "report_template.json")

    excluded_codes = build_holdout_excludes(holdouts_json)

    network_adj = build_network_adjustments_map(network_rows)
    shipper_cost = build_shipper_cost_map(shipper_cost_rows)
    active_labs_override = build_active_labs_override_map(lab_override_rows)

    runs_per_year_14 = 26
    runs_per_year_28 = 13

    panels_all = flatten_manifest_panels(panel_manifest)

    retained: List[Dict[str, Any]] = []
    for p in panels_all:
        if str(p.get("analysis_mode", "")).strip() != "review":
            continue
        code = str(p.get("panel_code", "")).strip()
        if code in excluded_codes:
            continue
        retained.append(p)

    panel_outputs: List[Dict[str, Any]] = []
    total_margin_14 = 0.0
    total_margin_28 = 0.0

    for p in retained:
        panel_code = str(p.get("panel_code", "")).strip()
        panel_name = str(p.get("panel_name", "")).strip()
        network_tier = str(p.get("network_tier", "")).strip()
        shipper_class = str(p.get("shipper_class", "")).strip()

        base_payment = resolve_base_payment_for_panel(p, contract_rows)
        network_adjustment = network_adj.get(network_tier, 0.0)
        total_payment = base_payment + network_adjustment

        override = active_labs_override.get(panel_code)
        if override is not None:
            active_labs = int(override[1])
        else:
            active_labs = to_int(p.get("default_active_labs"), default=0)

        shipper_cost_usd = shipper_cost.get(shipper_class, 0.0)
        reagent_cost_per_1000 = to_float(p.get("reagent_cost_per_1000_tests_usd"), 0.0)

        tests_per_lab_14 = to_float(p.get("tests_per_lab_per_run_14_day"), 0.0)
        tests_per_lab_28 = to_float(p.get("tests_per_lab_per_run_28_day"), 0.0)

        # 14-day
        annual_revenue_14 = total_payment * active_labs * runs_per_year_14
        annual_reagent_cost_14 = (
            reagent_cost_per_1000
            * active_labs
            * tests_per_lab_14
            * runs_per_year_14
            / 1000.0
        )
        annual_shipper_cost_14 = shipper_cost_usd * runs_per_year_14
        annual_margin_14 = annual_revenue_14 - annual_reagent_cost_14 - annual_shipper_cost_14

        # 28-day
        annual_revenue_28 = total_payment * active_labs * runs_per_year_28
        annual_reagent_cost_28 = (
            reagent_cost_per_1000
            * active_labs
            * tests_per_lab_28
            * runs_per_year_28
            / 1000.0
        )
        annual_shipper_cost_28 = shipper_cost_usd * runs_per_year_28
        annual_margin_28 = annual_revenue_28 - annual_reagent_cost_28 - annual_shipper_cost_28

        margin_diff = annual_margin_28 - annual_margin_14

        total_margin_14 += annual_margin_14
        total_margin_28 += annual_margin_28

        panel_outputs.append(
            {
                "panel_code": panel_code,
                "panel_name": panel_name,
                "network_tier": network_tier,
                "shipper_class": shipper_class,
                "active_labs": active_labs,
                "base_payment_per_run_per_lab_usd": r2(base_payment),
                "network_adjustment_per_run_per_lab_usd": r2(network_adjustment),
                "total_payment_per_run_per_lab_usd": r2(total_payment),
                "shipper_cost_usd": r2(shipper_cost_usd),
                "reagent_cost_per_1000_tests_usd": r2(reagent_cost_per_1000),
                "runs_per_year_14_day": runs_per_year_14,
                "runs_per_year_28_day": runs_per_year_28,
                "tests_per_lab_per_run_14_day": tests_per_lab_14,
                "tests_per_lab_per_run_28_day": tests_per_lab_28,
                "annual_revenue_14_day_usd": r2(annual_revenue_14),
                "annual_reagent_cost_14_day_usd": r2(annual_reagent_cost_14),
                "annual_shipper_cost_14_day_usd": r2(annual_shipper_cost_14),
                "annual_margin_14_day_usd": r2(annual_margin_14),
                "annual_revenue_28_day_usd": r2(annual_revenue_28),
                "annual_reagent_cost_28_day_usd": r2(annual_reagent_cost_28),
                "annual_shipper_cost_28_day_usd": r2(annual_shipper_cost_28),
                "annual_margin_28_day_usd": r2(annual_margin_28),
                "annual_margin_difference_28_minus_14_usd": r2(margin_diff),
            }
        )

    panel_outputs.sort(key=lambda x: x["panel_code"])

    total_margin_14_r = r2(total_margin_14)
    total_margin_28_r = r2(total_margin_28)
    total_diff = r2(total_margin_28_r - total_margin_14_r)
    abs_total_diff = r2(abs(total_diff))

    threshold = 6000.0
    if abs_total_diff < threshold:
        decision = "adopt_28_day"
    else:
        decision = "keep_14_day"

    justification = (
        f"Decision based on threshold ${threshold:,.2f}: "
        f"absolute total margin difference is ${abs_total_diff:,.2f}."
    )

    report = {
        "metadata": report_template.get("metadata"),
        "audit_notes": report_template.get("audit_notes"),
        "analysis": {
            "assumptions": {
                "runs_per_year_14_day": runs_per_year_14,
                "runs_per_year_28_day": runs_per_year_28,
                "shipper_shipments_per_run": 1,
                "decision_threshold_absolute_total_margin_difference_usd": r2(threshold),
            },
            "panels": panel_outputs,
            "totals": {
                "total_annual_margin_14_day_usd": total_margin_14_r,
                "total_annual_margin_28_day_usd": total_margin_28_r,
                "total_annual_margin_difference_28_minus_14_usd": total_diff,
                "absolute_total_margin_difference_usd": abs_total_diff,
            },
            "recommendation": {"decision": decision, "justification": justification},
        },
    }

    out_json = ROOT / "diagpanel_policy_report.json"
    with out_json.open("w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, cls=TwoDecimalFloatEncoder)
        f.write("\n")

    out_md = ROOT / "diagpanel_policy_summary.md"
    with out_md.open("w", encoding="utf-8") as f:
        f.write("Diagnostics Panel Policy: 14-day vs 28-day\n")
        f.write(f"Total annual margin (14-day): ${total_margin_14_r:,.2f}\n")
        f.write(f"Total annual margin (28-day): ${total_margin_28_r:,.2f}\n")
        f.write(f"Absolute difference: ${abs_total_diff:,.2f}\n")
        f.write(f"Decision: {decision}\n")


if __name__ == "__main__":
    main()

