import csv
import json
import math
from dataclasses import dataclass
from json.encoder import INFINITY, _make_iterencode, encode_basestring, encode_basestring_ascii
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple


ROOT = Path(__file__).resolve().parent


class TwoDecimalFloatEncoder(json.JSONEncoder):
    """JSON encoder that prints floats with exactly 2 decimal places.

    This keeps currency fields as JSON numbers (not strings) while ensuring the
    serialized artifact shows 2 decimals as required by the task.
    """

    def iterencode(self, o, _one_shot=False):
        # Largely based on Python's json.encoder.JSONEncoder.iterencode
        if self.check_circular:
            markers = {}
        else:
            markers = None

        _encoder = encode_basestring_ascii if self.ensure_ascii else encode_basestring

        def floatstr(
            value,
            allow_nan=self.allow_nan,
            _inf=INFINITY,
            _neginf=-INFINITY,
        ):
            if math.isnan(value):
                text = "NaN"
            elif value == _inf:
                text = "Infinity"
            elif value == _neginf:
                text = "-Infinity"
            else:
                # Force two decimals.
                return format(value, ".2f")
            if not allow_nan:
                raise ValueError(
                    "Out of range float values are not JSON compliant: " + repr(value)
                )
            return text

        _iterencode = _make_iterencode(
            markers,
            self.default,
            _encoder,
            self.indent,
            floatstr,
            self.key_separator,
            self.item_separator,
            self.sort_keys,
            self.skipkeys,
            _one_shot,
        )
        return _iterencode(o, 0)


def load_json(path: Path) -> Any:
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def load_csv(path: Path) -> List[Dict[str, str]]:
    with path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        return list(reader)


def is_blank(value: Optional[str]) -> bool:
    return value is None or str(value).strip() == ""


def to_float(value: Any, default: float = 0.0) -> float:
    if value is None:
        return default
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).strip()
    if s == "":
        return default
    try:
        return float(s)
    except ValueError:
        return default


def to_int(value: Any, default: int = 0) -> int:
    if value is None:
        return default
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    s = str(value).strip()
    if s == "":
        return default
    try:
        return int(float(s))
    except ValueError:
        return default


def r2(value: float) -> float:
    # A tiny epsilon reduces "-0.00" artifacts when values cancel.
    v = round(float(value) + 0.0, 2)
    if v == -0.0:
        return 0.0
    return v


def flatten_manifest_panels(panel_manifest: Dict[str, Any]) -> List[Dict[str, Any]]:
    panels: List[Dict[str, Any]] = []
    for cluster in panel_manifest.get("service_clusters", []):
        for panel in cluster.get("panels", []):
            panels.append(panel)
    return panels


def build_holdout_excludes(holdouts_json: Dict[str, Any]) -> set:
    excluded = set()
    for h in holdouts_json.get("holdouts", []):
        if str(h.get("holdout_state", "")).strip() == "exclude":
            code = str(h.get("panel_code", "")).strip()
            if code:
                excluded.add(code)
    return excluded


def resolve_base_payment_for_panel(
    panel: Dict[str, Any], contract_rows: List[Dict[str, str]]
) -> float:
    panel_name = str(panel.get("panel_name", "")).strip()
    alias_labels = panel.get("alias_labels")
    aliases: List[str] = []
