    """Return panel_code -> (rev, active_labs) for highest rev valid override."""

    best: Dict[str, Tuple[float, int]] = {}
    for r in rows:
        if str(r.get("approval", "")).strip() != "approved":
            continue
        panel_code = str(r.get("panel_code", "")).strip()
        rev_raw = r.get("rev")
        labs_raw = r.get("active_labs")
        if is_blank(panel_code) or is_blank(rev_raw) or is_blank(labs_raw):
            continue

        rev = to_float(rev_raw, default=float("nan"))
        if math.isnan(rev):
            continue
        labs = to_int(labs_raw, default=-1)
        if labs < 0:
            continue

        prev = best.get(panel_code)
        if prev is None or rev > prev[0]:
            best[panel_code] = (rev, labs)

    return best


